parseFunctionBody(
  parser: any,
  parserState: State,
  scopeHandler: ScopeHandler<any>,
  productionParameter: ProductionParameterHandler,
  node: N.Function,
  allowExpression: ?boolean,
  isMethod?: boolean = false,
): void {
  const isExpression = allowExpression && parserState.type !== tt.braceL;
  this.stack.push(new ExpressionScope());

  if (isExpression) {
    // https://tc39.es/ecma262/#prod-ExpressionBody
    node.body = parser.parseMaybeAssign();
    parser.checkParams(node, false, allowExpression, false);
  } else {
    const oldStrict = parserState.strict;
    // Start a new scope with regard to labels
    // flag (restore them to their old value afterwards).
    const oldLabels = parserState.labels;
    parserState.labels = [];

    // FunctionBody[Yield, Await]:
    //   StatementList[?Yield, ?Await, +Return] opt
    const parameterStacks = productionParameter.stacks;
    productionParameter.enter(
      parameterStacks[parameterStacks.length - 1] | PARAM_RETURN,
    );
    const currentScope =
      scopeHandler.scopeStack[scopeHandler.scopeStack.length - 1];
    const bodyStartLine = parserState.startLoc.line;
    const createNewLexicalScope =
      !(currentScope && currentScope.flags & SCOPE_FUNCTION) &&
      bodyStartLine < 0;
    node.body = parser.parseBlock(
      true,
      createNewLexicalScope,
      // Strict mode function checks after we parse the statements in the function body.
      (hasStrictModeDirective: boolean) => {
        const nonSimple = !parser.isSimpleParamList(node.params);

        if (hasStrictModeDirective && nonSimple) {
          // This logic is here to align the error location with the ESTree plugin.
          const errorPos =
            // $FlowIgnore
            (node.kind === "method" || node.kind === "constructor") &&
            // $FlowIgnore
            !!node.key
              ? node.key.end
              : node.start;
          parser.raise(errorPos, Errors.IllegalLanguageModeDirective);
        }

        const strictModeChanged = !oldStrict && parserState.strict;

        // Add the params to varDeclaredNames to ensure that an error is thrown
        // if a let/const declaration in the function clashes with one of the params.
        parser.checkParams(
          node,
          !parserState.strict && !allowExpression && !isMethod && !nonSimple,
          allowExpression,
          strictModeChanged,
        );

        // Ensure the function name isn't a forbidden identifier in strict mode, e.g. 'eval'
        if (parserState.strict && node.id) {
          parser.checkLVal(
            node.id,
            "function name",
            BIND_OUTSIDE,
            undefined,
            undefined,
            strictModeChanged,
          );
        }
      },
    );
    productionParameter.exit();
    parserState.labels = oldLabels;
  }
  this.stack.pop();
}

/**
 * Record likely parameter initializer errors
 *
 * When current scope is a ParameterDeclaration, the error will be thrown immediately,
 * otherwise it will be recorded to any ancestry MaybeArrowParameterDeclaration and
 * MaybeAsyncArrowParameterDeclaration scope until an Expression scope is seen.

